package com.ruoyi.warehouse.integrations;

import java.net.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.springframework.mock.env.MockEnvironment;
import static org.junit.jupiter.api.Assertions.*;

class IntegrationBoundaryTest {
    final Map<String,Object> credentials=Map.of("consumerKey","synthetic-reader","consumerSecret","synthetic-proof-value");
    @Test void authenticatedEncryptionIsRandomAndBoundToConnection(){byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);var vault=new IntegrationVault(Base64.getEncoder().encodeToString(key));String a=vault.seal("connection-a",credentials),b=vault.seal("connection-a",credentials);assertNotEquals(a,b);assertFalse(a.contains("synthetic"));assertEquals(credentials,vault.open("connection-a",a));assertEquals("CREDENTIAL_DECRYPTION_FAILED",assertThrows(IntegrationFailure.class,()->vault.open("connection-b",a)).code());assertThrows(IntegrationFailure.class,()->vault.open("connection-a",a.substring(0,a.length()-4)+"AAAA"));}
    @Test void missingKeyAndIncompleteCredentialPairsCannotBeSaved(){assertThrows(IntegrationFailure.class,()->new IntegrationVault("").seal("a",credentials));assertThrows(IllegalStateException.class,()->new IntegrationVault("invalid"));assertThrows(IntegrationFailure.class,()->IntegrationVault.validate(Map.of("consumerKey","only-key")));assertThrows(IntegrationFailure.class,()->IntegrationVault.validate(Map.of("consumerKey","bad:key","consumerSecret","value")));}
    @Test void urlsDoNotAcceptSecretsApiPathsOrOtherSchemes(){var transport=new IntegrationTransport("shop.example.com","",new MockEnvironment());assertEquals("https://shop.example.com/store",transport.canonicalSite("https://SHOP.example.com:443/store/"));for(String url:List.of("http://shop.example.com","https://user:pass@shop.example.com","https://shop.example.com?token=value","https://shop.example.com/#secret","https://shop.example.com/wp-json/wc/v3","https://shop.example.com/%2e%2e/admin","https://shop.example.com:8443","file:///etc/hosts"))assertThrows(IntegrationFailure.class,()->transport.canonicalSite(url),url);assertThrows(IntegrationFailure.class,()->transport.reader("https://other.example.com",credentials,Instant.now().plusSeconds(5)));}
    @Test void localFixturesRequireBothTestProfileAndLoopbackBinding(){assertThrows(IllegalStateException.class,()->new IntegrationTransport("","http://127.0.0.1:18888",new MockEnvironment()));var env=new MockEnvironment().withProperty("server.address","0.0.0.0");env.setActiveProfiles("warehouse-integration-test");assertThrows(IllegalStateException.class,()->new IntegrationTransport("","http://127.0.0.1:18888",env));}
    @Test void privateAndSpecialNetworkAddressesAreRejected()throws Exception{for(String host:List.of("127.0.0.1","10.1.2.3","169.254.169.254","100.64.1.2","192.168.1.1","198.18.0.1","203.0.113.1","::1","fc00::1","fe80::1","2001:db8::1","3fff::1","2002:7f00:1::1","64:ff9b::7f00:1"))assertFalse(IntegrationTransport.publicAddress(InetAddress.getByName(host)),host);for(String host:List.of("8.8.8.8","192.2.1.1","198.51.101.1","203.0.114.1"))assertTrue(IntegrationTransport.publicAddress(InetAddress.getByName(host)));assertTrue(IntegrationTransport.publicAddress(InetAddress.getByName("2606:4700:4700::1111")));}
    @Test void actualTransportKeepsAuthorizationOutOfUrlAndNeverFollowsRedirects()throws Exception{var hits=new AtomicInteger();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/wp-json/wc/v3/orders",exchange->{hits.incrementAndGet();assertNull(exchange.getRequestURI().getRawUserInfo());assertFalse(exchange.getRequestURI().toString().contains("synthetic"));assertEquals("Basic "+Base64.getEncoder().encodeToString("synthetic-reader:synthetic-proof-value".getBytes(StandardCharsets.UTF_8)),exchange.getRequestHeaders().getFirst("Authorization"));exchange.getResponseHeaders().add("Location","/forbidden");byte[] body="{}".getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(302,body.length);exchange.getResponseBody().write(body);exchange.close();});server.createContext("/forbidden",e->{hits.addAndGet(100);e.sendResponseHeaders(500,-1);e.close();});server.start();try{var response=fixture(server).reader(origin(server),credentials,Instant.now().plusSeconds(4)).get("/orders",Map.of("page","1"));assertEquals(302,response.status());assertEquals(1,hits.get());}finally{server.stop(0);}}
    @Test void duplicateJsonAndOversizedResponsesAreRefused()throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/wp-json/wc/v3/orders",e->{byte[] b="[{\"id\":1,\"id\":2}]".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.createContext("/wp-json/wc/v3/products",e->{e.sendResponseHeaders(200,2097153);e.close();});server.start();try{var reader=fixture(server).reader(origin(server),credentials,Instant.now().plusSeconds(4));assertEquals("REMOTE_RESPONSE_INVALID",assertThrows(IntegrationFailure.class,()->reader.get("/orders",Map.of())).code());assertEquals("REMOTE_RESPONSE_TOO_LARGE",assertThrows(IntegrationFailure.class,()->reader.get("/products",Map.of())).code());}finally{server.stop(0);}}
    @Test void anAbsoluteDeadlineStopsSlowResponseBodies()throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/wp-json/wc/v3/orders",e->{try{e.sendResponseHeaders(200,0);for(int n=0;n<60;n++){e.getResponseBody().write(' ');e.getResponseBody().flush();Thread.sleep(50);}}catch(Exception ignored){}finally{e.close();}});server.start();try{assertTimeoutPreemptively(Duration.ofSeconds(3),()->assertThrows(IntegrationFailure.class,()->fixture(server).reader(origin(server),credentials,Instant.now().plusMillis(250)).get("/orders",Map.of())));}finally{server.stop(0);}}
    private static String origin(HttpServer server){return "http://127.0.0.1:"+server.getAddress().getPort();}
    private static IntegrationTransport fixture(HttpServer server){var env=new MockEnvironment().withProperty("server.address","127.0.0.1");env.setActiveProfiles("warehouse-integration-test");return new IntegrationTransport("",origin(server),env);}
}
